{"id":"4e4b2381-0cd0-4f8d-bcf5-4e8f3dfdc35f","inserted_at":"2026-04-14T15:49:21.762599+00:00","updated_at":"2026-04-14T15:49:21.762599+00:00","type":"sql","name":"ESG Impact & Onboarding Setup","description":"","content":{"sql":"-- =========================================================================\r\n-- LOTO HUB - Intelligence Setup (Mandatory for ESG & Onboarding)\r\n-- Versione: 1.1 (Restoration Manifesto)\r\n-- Istruzioni: Copia e incolla questo script nel SQL Editor di Supabase.\r\n-- =========================================================================\r\n-- 1. Estensione Tabella PROFILES (Persistenza Onboarding)\r\nALTER TABLE profiles \r\nADD COLUMN IF NOT EXISTS onboarding_completed BOOLEAN DEFAULT false;\r\n-- 2. Creazione Tabella IMPACT_TRANSACTIONS (Audit Trail se mancante)\r\nCREATE TABLE IF NOT EXISTS impact_transactions (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    profile_id UUID REFERENCES profiles(id) ON DELETE CASCADE,\r\n    co2_saved FLOAT8 NOT NULL,\r\n    liters_saved FLOAT8 NOT NULL,\r\n    tokens_earned INTEGER NOT NULL,\r\n    xp_earned INTEGER NOT NULL,\r\n    is_takeaway BOOLEAN DEFAULT false,\r\n    party_size INTEGER DEFAULT 1,\r\n    action_type TEXT DEFAULT 'CHECKIN',\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()\r\n);\r\n-- 3. Definizione Motore ESG (process_esg_impact)\r\nCREATE OR REPLACE FUNCTION process_esg_impact(\r\n    user_id UUID,\r\n    p_co2 FLOAT8,\r\n    p_liters FLOAT8,\r\n    p_tokens INTEGER,\r\n    p_xp INTEGER,\r\n    p_takeaway BOOLEAN DEFAULT false,\r\n    p_party_size INTEGER DEFAULT 1\r\n) RETURNS VOID AS $$\r\nBEGIN\r\n    -- Aggiorna statistiche cumulative nel profilo\r\n    UPDATE profiles\r\n    SET \r\n        total_xp = total_xp + p_xp,\r\n        total_co2 = total_co2 + p_co2,\r\n        total_liters = total_liters + p_liters,\r\n        total_tokens = total_tokens + p_tokens,\r\n        onboarding_completed = true,\r\n        updated_at = now()\r\n    WHERE id = user_id;\r\n    -- Registra transazione certificata\r\n    INSERT INTO impact_transactions (\r\n        profile_id, co2_saved, liters_saved, tokens_earned, xp_earned, is_takeaway, party_size, action_type\r\n    ) VALUES (\r\n        user_id, p_co2, p_liters, p_tokens, p_xp, p_takeaway, p_party_size, 'CHECKIN'\r\n    );\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\nCOMMENT ON FUNCTION process_esg_impact IS 'Motore transazionale L.O.T.O. Hub per calcolo impatto e persistenza quiz.';","content_id":"4e4b2381-0cd0-4f8d-bcf5-4e8f3dfdc35f","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
